import * as pdfjs from './vendor/pdf.mjs';
import {Engine} from './inference.js';
pdfjs.GlobalWorkerOptions.workerSrc=new URL('./vendor/pdf.worker.mjs',import.meta.url).href;
const $=id=>document.getElementById(id),engine=new Engine(window.ort,status),drawing=$('drawing');let pdf=null,image=null,rows=[],busy=false,cancel=false,scale=1,fileName='',selected=-1;
function status(s){$('status').textContent=s;}
function buttons(){ $('extract').disabled=busy||!image;$('extract').textContent=busy?'Processing…':'Extract numbers ↗';$('file').disabled=busy;$('page').disabled=busy||!pdf;$('clear').disabled=busy||!rows.length;$('csv').disabled=busy||!rows.length;$('copy').disabled=busy||!rows.length;}
function fit(){scale=Math.min(1,($('viewport').clientWidth-40)/drawing.width,430/drawing.height);resize();}
function resize(){ $('sheet').style.width=drawing.width*scale+'px';$('sheet').style.height=drawing.height*scale+'px';$('zoom').textContent=Math.round(scale*100)+'%';}
async function render(){status('Rendering drawing…');if(pdf){const p=await pdf.getPage(Number($('page').value)),base=p.getViewport({scale:1}),vp=p.getViewport({scale:Math.min(3,3500/Math.max(base.width,base.height))});drawing.width=Math.ceil(vp.width);drawing.height=Math.ceil(vp.height);await p.render({canvasContext:drawing.getContext('2d'),viewport:vp}).promise;}else{drawing.width=image.width;drawing.height=image.height;drawing.getContext('2d').drawImage(image,0,0);}image=drawing;$('empty').hidden=true;$('sheet').hidden=false;$('dimensions').textContent=`${drawing.width} × ${drawing.height} px`;rows=[];update();fit();status('Drawing ready. Extract numbers to begin.');buttons();}
export async function open(file){if(!file||busy)return;if(file.size>50*1024*1024){status('Please choose a file smaller than 50 MB.');return;}busy=true;buttons();try{fileName=file.name;$('filename').textContent=fileName;pdf=null;const bytes=await file.arrayBuffer();if(/\.pdf$/i.test(file.name)){pdf=await pdfjs.getDocument({data:new Uint8Array(bytes)}).promise;$('page').replaceChildren(...Array.from({length:pdf.numPages},(_,i)=>new Option(String(i+1),String(i+1))));}else if(/^image\/(png|jpeg|webp)$/.test(file.type)){image=await createImageBitmap(new Blob([bytes],{type:file.type}));if(image.width*image.height>30000000){image.close();throw Error('Image is too large. Resize it below 30 megapixels.');}$('page').replaceChildren(new Option('1','1'));}else throw Error('Choose a PDF, PNG, JPG or WebP drawing.');await render();}catch(e){status('Could not open drawing: '+e.message);}finally{busy=false;buttons();$('file').value='';}}
$('file').onchange=e=>open(e.target.files[0]);$('page').onchange=async()=>{busy=true;buttons();try{await render();}catch(e){status(e.message);}finally{busy=false;buttons();}};
const vp=$('viewport');vp.ondragover=e=>{e.preventDefault();vp.classList.add('dragover');};vp.ondragleave=()=>vp.classList.remove('dragover');vp.ondrop=e=>{e.preventDefault();vp.classList.remove('dragover');open(e.dataTransfer.files[0]);};
function select(i){selected=i;update();const b=$('boxes').children[i];if(b)b.scrollIntoView({block:'nearest',inline:'nearest',behavior:'smooth'});}
function update(){ $('count').textContent=rows.length;$('results').hidden=!rows.length;$('result-empty').hidden=!!rows.length;$('rows').replaceChildren();$('boxes').replaceChildren();rows.forEach((r,i)=>{const tr=document.createElement('tr');if(i===selected)tr.className='selected';const num=document.createElement('td');num.textContent=i+1;num.style.cursor='pointer';num.onclick=()=>select(i);tr.append(num);for(const key of ['nominal','upper','lower']){const td=document.createElement('td'),input=document.createElement('input');input.value=r[key];input.setAttribute('aria-label',`${key} dimension ${i+1}`);input.oninput=()=>r[key]=input.value;input.onfocus=()=>{selected=i;for(const [j,b] of Array.from($('boxes').children).entries())b.classList.toggle('selected',i===j);};td.append(input);tr.append(td);}const conf=document.createElement('td');conf.textContent=Math.round(r.confidence*100);if(r.confidence<.8)conf.style.color='#b78531';tr.append(conf);const del=document.createElement('td'),btn=document.createElement('button');btn.textContent='×';btn.setAttribute('aria-label',`Delete dimension ${i+1}`);btn.disabled=busy;btn.onclick=()=>{rows.splice(i,1);update();};del.append(btn);tr.append(del);$('rows').append(tr);const b=document.createElement('div');b.className='box'+(i===selected?' selected':'');Object.assign(b.style,{left:r.x/drawing.width*100+'%',top:r.y/drawing.height*100+'%',width:r.w/drawing.width*100+'%',height:r.h/drawing.height*100+'%'});const label=document.createElement('span');label.textContent=i+1;b.append(label);b.onclick=()=>select(i);b.title=r.nominal;$('boxes').append(b);});buttons();}
$('extract').onclick=async()=>{busy=true;cancel=false;buttons();$('progress').hidden=false;$('progress').value=0;const old=rows;let next=[];try{await engine.extract(drawing,Number($('threshold').value),(r,i,total)=>{next.push(r);rows=next;update();$('progress').value=i/total*100;},()=>cancel);rows=next;update();status(rows.length?`Complete — ${rows.length} dimensions. Review values before exporting.`:'No dimension numbers detected. Try a clearer drawing or lower detection confidence.');}catch(e){rows=old;update();console.error(e);status('Extraction failed: '+e.message+'. You can retry.');}finally{busy=false;$('progress').hidden=true;update();}};
$('clear').onclick=()=>{rows=[];update();status('Results cleared.');};$('showboxes').onchange=e=>$('boxes').hidden=!e.target.checked;$('fit').onclick=fit;$('zoomin').onclick=()=>{scale=Math.min(3,scale*1.25);resize();};$('zoomout').onclick=()=>{scale=Math.max(.05,scale/1.25);resize();};$('threshold').oninput=e=>$('threshold-value').textContent=Math.round(e.target.value*100)+'%';
function csvCell(v){v=String(v);if(/^[=\t\r@]/.test(v)||/^[+-](?!\d)/.test(v))v="'"+v;return '"'+v.replaceAll('"','""')+'"';}
$('csv').onclick=()=>{const data=[['Page','No','Nominal','Upper tolerance','Lower tolerance','Confidence'],...rows.map((r,i)=>[$('page').value,i+1,r.nominal,r.upper,r.lower,Math.round(r.confidence*100)+'%'])].map(r=>r.map(csvCell).join(',')).join('\r\n');const a=document.createElement('a'),url=URL.createObjectURL(new Blob(['\uFEFF'+data],{type:'text/csv;charset=utf-8'}));a.href=url;a.download=fileName.replace(/\.[^.]+$/,'')+'-numbers.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);status('CSV exported.');};$('copy').onclick=async()=>{try{await navigator.clipboard.writeText(rows.map(r=>[r.nominal,r.upper,r.lower].join('\t')).join('\n'));status('Numbers copied.');}catch{status('Clipboard unavailable. Use Export CSV.');}};
window.addEventListener('resize',()=>{if(image)fit();});
